head.script:
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일(spinne_SKT-689_(WSQ-2168)_main.xml)을 실행 후 첫번째줄 가운데의 아래로 3번째 spinner에 시분초(100000)를 입력한다.
    //1. Run the sample file (spinne_SKT-689_ (WSQ-2168) _main.xml) and enter the time in seconds (100000) in the third spinner down the first line.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_13_downButton').focus()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_13___input').setValue('100000')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_13___input').blur()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. 10:00:00이 입력되어 진다.
    // 1. 10:00:00 is entered.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('wq_uuid_13___input').realValue == '10:00:00'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. spinner의 증감버튼을 클릭한다.
    //2. Click the Increase button on the spinner.
    //Verify 2. 3초씩 증감되어진다.
    //2. It is increased or decreased by 3 seconds.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_13_upButton_image').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('wq_uuid_13___input').realValue == '10:00:03'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 26-Feb-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
